import csv, pathlib, html, json
root=pathlib.Path(__file__).resolve().parents[1]
rows=list(csv.DictReader(open(root/'assets/image-manifest.csv')))
photos=[x for x in rows if x['category']!='Guest artwork']
# URLs are original public Wix uploaded media links, not upscaled thumbnails
for row in rows:
 row['title']=row['asset_id'].replace('-',' ').title()
 row['url']='/assets/restored/'+row['asset_id']+'.jpg' if (root/'assets/restored'/(row['asset_id']+'.jpg')).exists() else row['source_original_media_url']
(root/'assets/photos.json').write_text(json.dumps(rows,indent=2))
hero=photos[2]['url'] if len(photos)>2 else rows[0]['url']
style='''@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap');:root{--forest:#1e372b;--sage:#7c8b76;--cream:#f8f5ec;--sand:#eae1d1;--gold:#b08b52;--ink:#252c27}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.75 'DM Sans',sans-serif}h1,h2,h3{font-family:'Playfair Display',Georgia,serif;line-height:1.16;font-weight:500}h1{font-size:clamp(3rem,6.4vw,6.8rem);margin:.3em 0}h2{font-size:clamp(2rem,4vw,3.9rem)}h3{font-size:1.6rem}a{color:inherit}img{max-width:100%}.top{padding:9px 6%;background:var(--forest);color:#fff;text-align:center;font-size:.8rem;letter-spacing:.04em}.top a{color:inherit}.nav{display:flex;justify-content:space-between;align-items:center;gap:22px;padding:12px 5%;background:#fff;position:sticky;top:0;z-index:10;box-shadow:0 3px 16px #142b1712}.logo{display:flex;align-items:center;gap:12px;text-decoration:none;font-family:Georgia,serif;letter-spacing:.07em;font-weight:bold;font-size:18px}.logo img{width:72px;height:62px;object-fit:contain}.links{display:flex;align-items:center;gap:20px;font-size:13px;font-weight:600}.links a{text-decoration:none}.links a:hover{text-decoration:underline}.btn{display:inline-block;background:var(--forest);color:white;text-decoration:none;padding:14px 23px;border-radius:2px;font-weight:700;text-transform:uppercase;font-size:12px;letter-spacing:.14em}.btn.alt{background:#fff;color:var(--forest)}.hero{min-height:78vh;display:flex;align-items:center;background:linear-gradient(90deg,#102416db,#10241640),url('HEROURL') center/cover;color:white;padding:8% 9%}.hero>div{max-width:840px}.eyebrow{text-transform:uppercase;letter-spacing:.21em;font-size:11px;font-weight:700;color:var(--gold)}.hero .eyebrow{color:#ead4a6}.hero p{max-width:590px;font-size:1.15rem}.wrap{max-width:1190px;margin:auto;padding:78px 25px}.split{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.split img{width:100%;min-height:380px;object-fit:cover}.highlight{background:var(--sand)}.muted{color:#647366}.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.2em;font-weight:bold;color:#8a764e}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{background:white;padding:30px;min-height:210px;border-top:3px solid var(--gold)}.card h3{margin:0 0 12px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.grid figure{margin:0;position:relative;background:#ddd;aspect-ratio:4/3;overflow:hidden}.grid img{width:100%;height:100%;object-fit:cover;transition:transform .3s}.grid img:hover{transform:scale(1.045)}.grid figcaption{background:#20392ccc;color:#fff;position:absolute;bottom:0;left:0;right:0;padding:8px 12px;font-size:11px;text-transform:capitalize}.dark{background:var(--forest);color:#fff}.dark .kicker{color:#e4bd7c}.footer{background:#14291f;color:#fff;padding:55px 7%;display:grid;grid-template-columns:2fr 1fr;gap:20px}.footer a{color:inherit}ul{padding-left:20px}li{padding-bottom:5px}.original{border-left:3px solid var(--gold);padding-left:21px}.note{font-size:12px;color:#59675c}.main-head{padding:75px 8% 55px;background:var(--sand)}.main-head h1{font-size:clamp(2.8rem,5vw,5rem)}.photos-note{margin:16px 0 30px}summary{cursor:pointer;font-weight:700;padding:15px 0;border-bottom:1px solid #c9c9b8}@media(max-width:850px){.links{gap:8px;flex-wrap:wrap;justify-content:flex-end}.links a{font-size:11px}.logo img{width:56px;height:50px}.split{grid-template-columns:1fr}.cards,.grid{grid-template-columns:repeat(2,1fr)}.hero{min-height:65vh}.footer{grid-template-columns:1fr}}@media(max-width:540px){.nav{align-items:flex-start;flex-direction:column}.links{width:100%;justify-content:space-between}.links a{font-size:10px}.links .btn{padding:9px}.hero{padding:13% 7%}.cards,.grid{grid-template-columns:1fr}.wrap{padding:50px 20px}.split{gap:22px}}'''.replace('HEROURL',hero)
(root/'assets/site.css').write_text(style)
js='''const manifest=window.BK_PHOTOS||[];document.querySelectorAll('[data-gallery]').forEach(g=>{const n=Number(g.dataset.gallery)||1000;g.innerHTML=manifest.slice(0,n).map((p,i)=>`<figure><a href="${p.url}" target="_blank" rel="noopener" aria-label="View original B and K cabin photograph ${i+1}"><img loading="lazy" alt="Original B and K Cabins Gloster Mississippi guest and recreation photo ${i+1}" src="${p.url}" onerror="this.closest('figure').style.display='none'"></a><figcaption>${p.category} • ${i+1}</figcaption></figure>`).join('')});'''
(root/'assets/site.js').write_text(js)
(root/'assets/photos.js').write_text('window.BK_PHOTOS='+json.dumps(photos)+';')
