def page(path,title,desc,body):
 p=root/path; p.mkdir(exist_ok=True,parents=True)
 canon='https://bandkcabins.com/'+('' if path=='.' else path+'/')
 # schema facts only verified from original public site
 schema={'@context':'https://schema.org','@type':'LodgingBusiness','name':'B & K Cabins','url':'https://bandkcabins.com/','description':'Private cabin rental near Homochitto National Forest in Gloster, Mississippi.','address':{'@type':'PostalAddress','addressLocality':'Gloster','addressRegion':'MS','addressCountry':'US'},'telephone':'+1-601-341-2663','email':'bandkcabins@gmail.com'}
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="canonical" href="{canon}"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:url" content="{canon}"><meta property="og:image" content="https://bandkcabins.com/assets/bk-logo.png"><link rel="stylesheet" href="/assets/site.css"><link rel="icon" href="/assets/bk-logo.png"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>{nav}<main>{body}</main>{foot}<script src="/assets/photos.js"></script><script defer src="/assets/site.js"></script></body></html>'''
 (p/'index.html').write_text(out)
home='''<section class="hero"><div><span class="eyebrow">Gloster, Mississippi • Creekside Cabin Getaway</span><h1>Welcome To The<br>B & K Cabins</h1><p>Are you looking for an adventure, fresh sights, or even somewhere to just get away from it all?</p><a href="/the-cabin/" class="btn alt">Explore the cabin</a> <a class="btn" href="/contact/">Plan your stay</a></div></section><section class="wrap split"><div><div class="kicker">The original B & K story</div><h2>About Us</h2><div class="original"><p>The B & K Cabin can be found in Gloster, MS off a secondary road, nestled in the privacy of the Homochitto National Forest. Spanning amongst six acres of breathtaking beauty, you're sure to find privacy and tranquility you never knew existed.</p><p>We have been delighted to host hundreds of families & groups over the years.</p><p>It is rewarding to know that after their trip, guests find themselves anticipating & planning their next to return to the cabins comfort and beauty.</p></div></div><img src="'''+hero+'''" alt="B and K Cabins original property photograph"></section><section class="highlight"><div class="wrap"><div class="kicker">Nature, relaxation & memories</div><h2>A private cabin getaway near Homochitto National Forest</h2><p>Looking for a secluded cabin rental in Gloster, Mississippi? The B & K offers a comfortable base for exploring the outdoors, spending time together and enjoying a quieter pace. Browse our original cabin photographs, amenities and guest information before you plan your visit.</p><div class="cards"><div class="card"><h3>Six peaceful acres</h3><p>A wooded Mississippi getaway with space to breathe.</p></div><div class="card"><h3>Creek & sandbar</h3><p>Enjoy the outdoor recreation area and creek setting.</p></div><div class="card"><h3>Bring the family</h3><p>Children and four-legged family members are welcome, subject to current house rules.</p></div></div></div></section><section class="wrap"><h2>Why book your stay with us?</h2><div class="original"><p>The B & K Cabin welcomes all guests year round, including all holidays.</p><p>And yes, by "all guests" this means your four legged family members, children of all ages, & your mother-in-law are welcomed to tag along & enjoy the fun!</p><p>Guests come through for simple getaways & family vacations quite often, both impromptu or meticulously planned.</p><p>Guests can do this due to the simple fact that we provide ample amenities & make booking your reservation easy, the way it should be.</p><p>In addition to typical visits, we have also served groups for weddings, yoga retreats, team building trips, family reunions, birthdays & anniversaries.</p></div><p class="note">Contact Tina about current availability, guest limits, pets and gatherings before making plans.</p></section><section class="wrap"><div class="kicker">Original gallery</div><h2>A glimpse of the B & K</h2><div class="grid" data-gallery="6"></div><p><a class="btn" href="/photos/">Explore all photos</a></p></section><section class="dark"><div class="wrap"><h2>Just call, text, or email Tina!</h2><p>We would love to help you plan a relaxing Mississippi getaway.</p><a class="btn alt" href="tel:+16013412663">Call (601) 341-2663</a> <a class="btn" href="mailto:bandkcabins@gmail.com?subject=B%26K%20Cabins%20Stay%20Inquiry">Email Tina</a></div></section>'''
page('.', 'B & K Cabins | Secluded Creekside Cabin Rental in Gloster, MS','Plan a private cabin getaway in Gloster, Mississippi near Homochitto National Forest. Explore amenities, original photos, creek and sandbar, and contact Tina to book.',home)
head=lambda name,tag,copy:f'<header class="main-head"><div class="kicker">{tag}</div><h1>{name}</h1><p>{copy}</p></header>'
page('the-cabin','The Cabin | B & K Cabins Gloster Mississippi','Explore the private wooded cabin near Homochitto National Forest, Gloster MS, with a shaded porch, comfortable sleeping and peaceful surroundings.',head('The Cabin','Your home away from home','A comfortable Gloster, Mississippi cabin tucked into the forest.')+'''<section class="wrap split"><div><h2>Come make yourself at home</h2><div class="original"><p>The Cabin sleeps 6 guests total, but you could always bring a small air mattress or cot along if you need the extra spots to rest after a fun day.</p><p>The large front porch is shaded & invites a calm breeze in while still offering a comfortable place to relax. The interior is well insulated and offers refuge as you relax with excellent heating & cooling.</p></div><p class="note">Please confirm the maximum permitted occupancy with Tina before booking; older published guest counts may differ.</p><p><a class="btn" href="/amenities/">See cabin amenities</a></p></div><div class="grid" data-gallery="4"></div></section>''')
amgroups=[('Indoor Kitchen',['Electric Stove','Toaster','Full Size Refrigerator','Microwave','Kitchen Sink with provided dish soap','Coffee Pot & Filters (Don’t forget your coffee and creamer!)','Pots & Pans','Cookware','Eating Utensils, Plates, & Drinking Glasses','Salt & Pepper','Paper Towels','Zip Lock bags (Gallons & Quarts)','Aluminum Foil']),('Beds, Entertainment, & Comfort',['All Linens & Paper Products Are Provided For The Beds & Bathrooms','Private Queen sized bed','Semi-Private Twin Size Bunk Bed','Sofa with pullout bed','Heating & Cooling','Full Bathroom (Bath & Hand Soap Provided; Guests Should Bring Shampoo)','TV with DVD Player','Board Games']),('Outdoor Recreational Area',['Charcoal grill (Guests Must Bring Charcoal & Lighter Fluid)','Picnic area','Two handcrafted 16’ picnic tables with seating','Large Sink with Dawn Soap Provided','Ample Counter Space','Covered Swing & Bench Seating Area','Hammock','Fire Pit Seating: 2 benches and 6 Chairs','(Feel free to bring your favorite fold out chairs)']),('Bath House',['Washer & Dryer (Tide & Snuggle Provided)','Shower (Bath & Hand Soap Provided; Guests Should Bring Shampoo)','Sink','Commode']),('Sand Bar & Creek',['Guests should bring personal beach towels','3 Full Size Beach Loungers','1 Low Sling Chair','4 Beach Umbrellas','Some Sand Toys'])]
ams=''.join('<div class="card"><h3>'+html.escape(title)+'</h3><ul>'+''.join('<li>'+html.escape(k)+'</li>' for k in items)+'</ul></div>' for title,items in amgroups)
page('amenities','Cabin Amenities | Kitchen, Bathhouse, Creek & More | B & K Cabins','See the full B & K cabin amenity checklist: equipped kitchen, linens, shaded porch, bathhouse, laundry, fire pit, creek and sandbar in Gloster, Mississippi.',head('Amenities','Pack less • Enjoy more','Here is the original B & K Cabins amenity information, organized to help you prepare for your stay.')+'<section class="wrap"><div class="cards">'+ams+'</div><p class="note">Amenities list reflects the original website; please confirm current availability of individual items with Tina.</p></section>')
page('photos','Photos | B & K Cabins Creekside Getaway Gloster MS','Explore photos from B & K Cabins in Gloster, Mississippi, including guest memories and outdoor recreation near Homochitto National Forest.',head('Photos','Our gallery of memories','Additional photos of the cabin’s outdoor recreation along with photos, videos, & artwork created or captured by our guests.')+'''<section class="wrap"><div class="original"><p>Want to see your contribution added to our gallery?</p><p>Send us an email with your photos, videos, or artwork!</p><p>We would love to share your memories with all prior & future guests.</p><p>This is our bath house outside near the recreation area! It serves as our second restroom, shower, as well as where you'll find the washer & dryer.</p><p>Check out this Drone Footage captured by our guest S. J. Owens during his stay!</p><p>A painting created by our guest Steve Gill during his stay.</p></div><p class="photos-note note">Original images are sourced from the existing Wix public photo gallery. Some may load slowly; improved locally hosted versions will be substituted when the originals are fully recovered.</p><div class="grid" data-gallery="100"></div></section>''')
page('faq','Frequently Asked Questions | B & K Cabins Mississippi','Frequently asked questions about staying at B & K Cabins in Gloster MS, including what to bring, pets, gatherings and booking inquiries.',head('Frequently Asked Questions','Additional Info','A few useful things to know before your trip to the B & K.')+'''<section class="wrap"><details><summary>What should I bring?</summary><p>Don’t forget your coffee and creamer, shampoo, personal beach towels, and charcoal and lighter fluid if you plan to use the grill. Take a look at our <a href="/amenities/">full amenities page</a> for the original detailed packing notes.</p></details><details><summary>Are pets welcome?</summary><p>Our original website welcomes four-legged family members! Please check current pet requirements with Tina before arrival.</p></details><details><summary>Can we plan a gathering or event?</summary><p>Our original site mentions weddings, yoga retreats, team-building trips, family reunions, birthdays, and anniversaries. Please contact Tina to discuss what is currently permitted.</p></details><details><summary>How do we ask about availability?</summary><p>Just call or text Tina at <a href="tel:+16013412663">(601) 341-2663</a>, or email <a href="mailto:bandkcabins@gmail.com">bandkcabins@gmail.com</a>.</p></details><details><summary>Where is the cabin?</summary><p>B & K Cabins is in Gloster, Mississippi, near Homochitto National Forest. Contact Tina for detailed arrival directions.</p></details></section>''')
page('contact','Contact Tina & Plan Your Stay | B & K Cabins Gloster MS','Ask Tina about availability, rates, pets, gatherings, and your upcoming stay at B & K Cabins in Gloster, Mississippi.',head('Contact Us','Just call, text, or email Tina!','Have a question about booking, available dates or what to bring? Get in touch.')+'''<section class="wrap split"><div><h2>We’d love to hear from you.</h2><p><strong>Call or text:</strong><br><a href="tel:+16013412663">(601) 341-2663</a></p><p><strong>Email:</strong><br><a href="mailto:bandkcabins@gmail.com">bandkcabins@gmail.com</a></p><p><a class="btn" href="mailto:bandkcabins@gmail.com?subject=B%26K%20Cabins%20Availability%20Inquiry&body=Hi%20Tina%2C%0A%0AI%20would%20like%20to%20ask%20about%20availability%20for%3A%0AArrival%20date%3A%0ADeparture%20date%3A%0ANumber%20of%20guests%3A%0APets%3A%0A%0AThank%20you%21">Ask about availability</a></p><p class="note">No booking or payment is collected on this website. Confirm availability and rates directly with Tina.</p></div><img src="/assets/bk-logo.png" alt="B and K Cabins Gloster Mississippi woodland cabin logo" style="object-fit:contain;min-height:200px"></section>''')
